import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.OWFDNrRT.js";const g=JSON.parse('{"title":"ADR-002: Native Menu Injector Design","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-015-native-menu-injector.md","filePath":"adr/ADR-015-native-menu-injector.md","lastUpdated":1774507673000}'),i={name:"adr/ADR-015-native-menu-injector.md"};function s(r,e,c,d,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="adr-002-native-menu-injector-design" tabindex="-1">ADR-002: Native Menu Injector Design <a class="header-anchor" href="#adr-002-native-menu-injector-design" aria-label="Permalink to &quot;ADR-002: Native Menu Injector Design&quot;">​</a></h1><h2 id="status-accepted" tabindex="-1">Status: Accepted <a class="header-anchor" href="#status-accepted" aria-label="Permalink to &quot;Status: Accepted&quot;">​</a></h2><h2 id="date-2026-03-24" tabindex="-1">Date: 2026-03-24 <a class="header-anchor" href="#date-2026-03-24" aria-label="Permalink to &quot;Date: 2026-03-24&quot;">​</a></h2><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>DINOForge needs a discoverable entry point into its mod menu that does not require players to memorise the F10 hotkey. DINO&#39;s UI is rendered via Unity UGUI and its main menu persists as a set of standard <code>Canvas</code> / <code>Button</code> hierarchy objects. Injecting a sibling &quot;Mods&quot; button next to the native &quot;Settings&quot; button is the lowest-friction, most idiomatic approach: it reuses the game&#39;s own visual skin and appears exactly where players already look for options.</p><h3 id="dino-boot-sequence-constraints" tabindex="-1">DINO Boot Sequence Constraints <a class="header-anchor" href="#dino-boot-sequence-constraints" aria-label="Permalink to &quot;DINO Boot Sequence Constraints&quot;">​</a></h3><p>DINO takes 60–90 seconds to fully boot. During that window:</p><ol><li>Unity loads asset bundles from <code>StreamingAssets/aa/StandaloneWindows64/</code> (4.2 GB + 2.1 GB bundles).</li><li>An <code>InitialGameLoader</code> splash/loading screen is shown; the user must click through it manually before the main menu becomes visible.</li><li>The main-menu <code>Canvas</code> and its child buttons are not instantiated until after the splash screen is dismissed.</li></ol><p>Any scan for UI elements that runs before the player advances past the splash screen will find zero suitable canvases and must retry without error.</p><h3 id="why-scenemanager-activescenechanged-was-chosen-as-the-scan-trigger" tabindex="-1">Why <code>SceneManager.activeSceneChanged</code> Was Chosen as the Scan Trigger <a class="header-anchor" href="#why-scenemanager-activescenechanged-was-chosen-as-the-scan-trigger" aria-label="Permalink to &quot;Why \`SceneManager.activeSceneChanged\` Was Chosen as the Scan Trigger&quot;">​</a></h3><p><code>SceneManager.activeSceneChanged</code> fires on the Unity main thread, immediately after a scene transition completes. This gives two guarantees that alternative mechanisms cannot provide:</p><ul><li><strong>Thread safety</strong>: All UGUI object traversal (<code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code>, <code>GetComponentsInChildren&amp;lt;Button&amp;gt;()</code>) is safe only on the main thread. Calling these APIs from any other thread during asset loading causes a deadlock inside Unity&#39;s native object manager.</li><li><strong>Timeliness</strong>: The callback fires as soon as the incoming scene is fully loaded, so newly instantiated UI objects are already present in the hierarchy.</li></ul><p>Additional scans are performed on a <code>RescanInterval = 2f</code> second timer inside <code>Update()</code> to handle cases where the menu canvas becomes active after the scene-changed event (e.g., delayed activation by DINO&#39;s own initialisation scripts).</p><h3 id="why-periodic-background-scanning-was-removed" tabindex="-1">Why Periodic Background Scanning Was Removed <a class="header-anchor" href="#why-periodic-background-scanning-was-removed" aria-label="Permalink to &quot;Why Periodic Background Scanning Was Removed&quot;">​</a></h3><p>An earlier design polled for canvases from the <code>DINOForge-KeyInputWatcher</code> background thread at 50 ms intervals. This caused a deadlock during asset loading:</p><ul><li>Unity&#39;s asset-loading subsystem holds an internal lock while deserialising bundles.</li><li><code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> attempts to acquire the same lock from the background thread.</li><li>With the main thread blocked in asset I/O, neither thread can proceed.</li></ul><p>The deadlock manifested as a hard freeze (no crash, no log output) lasting until the OS killed the process. The fix was to move all <code>Resources.FindObjectsOfTypeAll</code> calls exclusively onto the main thread and to rely on <code>SceneManager.activeSceneChanged</code> (plus <code>Update()</code> polling) instead of background-thread scheduling. The watcher thread comment in <code>Plugin.cs</code> documents this explicitly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// NOTE: NativeMenuInjector scanning is NOT done from this watcher thread —</span></span>
<span class="line"><span>// Resources.FindObjectsOfTypeAll&lt;Canvas&gt;() can deadlock when called from</span></span>
<span class="line"><span>// a background thread during Unity&#39;s asset-loading phase.</span></span>
<span class="line"><span>// Scans are triggered by OnActiveSceneChanged (main-thread-safe).</span></span></code></pre></div><h3 id="why-the-button-is-injected-into-dino-s-native-menu" tabindex="-1">Why the Button Is Injected into DINO&#39;s Native Menu <a class="header-anchor" href="#why-the-button-is-injected-into-dino-s-native-menu" aria-label="Permalink to &quot;Why the Button Is Injected into DINO&#39;s Native Menu&quot;">​</a></h3><p>Alternatives considered:</p><table tabindex="0"><thead><tr><th>Alternative</th><th>Rejected Because</th></tr></thead><tbody><tr><td>Separate overlay canvas (always-on)</td><td>Covers game elements; breaks DINO&#39;s pause flow</td></tr><tr><td>F10 hotkey only</td><td>Non-discoverable; players unfamiliar with mods will never find it</td></tr><tr><td>BepInEx Configuration Manager</td><td>Requires a separate plugin dependency; not integrated with DINOForge&#39;s pack system</td></tr><tr><td>ImGui / Dear ImGui</td><td>No maintained Unity Mono port compatible with Unity 2021.3 + BepInEx 5</td></tr></tbody></table><p>Cloning the native &quot;Settings&quot; or &quot;Options&quot; button and re-labelling it &quot;Mods&quot; is safe and self-contained: it inherits all UGUI visuals (colours, sprite states, font, layout) from the existing button, requires no additional assets, and lives inside the canvas that DINO already shows and hides correctly during pause/resume transitions.</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>NativeMenuInjector</code> is a <code>MonoBehaviour</code> attached to the <code>DINOForge_Root</code> persistent GameObject. It:</p><ol><li>Subscribes to <code>SceneManager.activeSceneChanged</code> in <code>Awake()</code>.</li><li>On each scene change and on a 2-second <code>Update()</code> timer, calls <code>TryInjectMenuButton()</code> on the main thread.</li><li><code>TryInjectMenuButton()</code> enumerates all active <code>Canvas</code> objects via <code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code>, searches each for a button labelled &quot;Settings&quot; or &quot;Options&quot;, and — if found — clones that button, relabels it &quot;Mods&quot;, wires its <code>onClick</code> to <code>IModMenuHost.Toggle()</code>, and isolates its UGUI navigation graph (<code>Navigation.Mode.None</code>) so it does not interfere with DINO&#39;s controller/keyboard navigation.</li><li>Once injection succeeds, <code>Update()</code> does nothing until the injected button is destroyed (e.g., on scene unload), at which point the cycle restarts automatically.</li><li>A <code>static Action? OnScanNeeded</code> delegate is provided as an external trigger for test harnesses or future tooling that need to force a re-scan from a known main-thread context.</li></ol><p><code>SceneManager.activeSceneChanged</code> is the primary trigger. The 2-second <code>Update()</code> poll is the secondary trigger for late-activating canvases.</p><hr><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Players discover the mod menu without documentation.</li><li>The injected button is visually indistinguishable from native buttons.</li><li>All UGUI traversal is main-thread-only, eliminating the deadlock class.</li><li>Injection is idempotent and self-healing: re-injects on scene reload, detects pre-existing button to avoid duplicates.</li><li>Full diagnostic logging (attempt counter, session ID, per-step state) aids debugging without impacting production performance.</li></ul><h3 id="negative-limitations" tabindex="-1">Negative / Limitations <a class="header-anchor" href="#negative-limitations" aria-label="Permalink to &quot;Negative / Limitations&quot;">​</a></h3><ul><li><strong>InitialGameLoader dependency</strong>: The user must manually click through DINO&#39;s splash screen before the main menu appears. There is no programmatic way to skip or detect this step without hooking DINO internals. The injector will silently retry until the menu is ready.</li><li><strong>Canvas name independence</strong>: The injector cannot rely on fixed canvas names because DINO may change them across game versions. It instead searches all active canvases for a &quot;Settings&quot; or &quot;Options&quot; button text, which is more fragile than a stable identifier but more resilient to canvas renames.</li><li><strong>UGUI-only</strong>: The approach is specific to Unity&#39;s UGUI system. If DINO ever migrates to UI Toolkit, the injector will need to be replaced.</li><li><strong>No EventSystem focus transfer</strong>: The injected button deliberately does not steal EventSystem focus (<code>currentSelectedGameObject</code>) to avoid triggering DINO&#39;s native navigation handlers unexpectedly. This means keyboard/gamepad navigation does not auto-select the Mods button.</li><li><strong>Scan cost</strong>: <code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> traverses all loaded Unity objects. In a scene with many objects this has a small GC allocation cost. The 2-second scan interval keeps this negligible.</li><li><strong>Persistent root required</strong>: <code>NativeMenuInjector</code> relies on the <code>DINOForge_Root</code> persistent GameObject surviving scene transitions. If that object is destroyed, the injector is lost and no resurrection path currently exists for the injector specifically (resurrection targets <code>RuntimeDriver</code>).</li></ul><hr><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h2><ul><li><strong>File</strong>: <code>src/Runtime/UI/NativeMenuInjector.cs</code></li><li><strong>Namespace</strong>: <code>DINOForge.Runtime.UI</code></li><li><strong>Wired by</strong>: <code>RuntimeDriver.Initialize()</code> via <code>PersistentRoot.AddComponent&amp;lt;NativeMenuInjector&amp;gt;()</code></li><li><strong>Canvas candidates list</strong> (<code>CanvasCandidateNames</code>): kept for reference diagnostics; actual filtering uses the Settings/Options button text, not canvas names.</li><li><strong>Button cloning</strong>: delegated to <code>NativeUiHelper.CloneButton()</code> and <code>NativeUiHelper.PositionAfterSibling()</code>.</li><li><strong>Visual sync</strong>: <code>SyncButtonVisualStyle()</code> mirrors transition type, color block, sprite state, animation triggers, and <code>UnityEngine.UI.Text</code> properties from source to clone.</li><li><strong>Click debounce</strong>: 200 ms (<code>ClickDebounceSeconds</code>) using <code>Time.unscaledTime</code> to prevent double-fire during rapid UGUI event delivery.</li><li><strong>Duplicate guard</strong>: before cloning, scans the parent&#39;s children for an existing <code>DINOForge_ModsButton</code> prefixed object and reuses it rather than injecting a second button.</li><li><strong>Debug log</strong>: supplemental file log at <code>BepInEx/dinoforge_debug.log</code> via <code>WriteDebug()</code> (non-blocking, <code>Monitor.TryEnter</code> with 100 ms timeout).</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><code>src/Runtime/UI/NativeMenuInjector.cs</code> — full implementation</li><li><code>src/Runtime/Plugin.cs</code> — <code>StartResurrectionWatcher()</code> comment documenting the deadlock rationale</li><li><code>docs/specs/SPEC-002-native-menu-injector.md</code> — companion specification</li><li>Memory note: <code>project_dino_runtime_execution_model.md</code> — definitive map of safe execution contexts in DINO</li><li>ADR-009: Runtime Orchestration — persistent root and <code>RuntimeDriver</code> lifecycle</li></ul>`,40)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
